public class RemoveMatchesTests {

    private Role roleA;
    private Role roleB;
    private Role roleC;

    @Before
    public void setUp() {
        roleA = new Role("roleA");
        roleB = new Role("roleB");
        roleC = new Role("roleC");
    }

    @Test
    public void testRemoveMatchesWithEmptyMatchedBy() {
        // Given: roleA has no matchedBy relationships
        assertTrue(roleA.matchedBy.isEmpty());

        // When: removeMatches is called
        roleA.removeMatches();

        // Then: matchedBy remains empty
        assertTrue(roleA.matchedBy.isEmpty());
    }

    @Test
    public void testRemoveMatchesWithSingleMatch() {
        // Given: Set up a match relationship where roleB is matched by roleA
        roleA.matched.put(roleB.name, roleB);
        roleB.matchedBy.put(roleA.name, roleA);

        // When: removeMatches is called on roleA
        roleA.removeMatches();

        // Then: roleA's matchedBy is cleared and roleB's matched no longer contains roleA
        assertTrue(roleA.matchedBy.isEmpty());
        assertNull(roleB.matched.get(roleA.name));
    }

    @Test
    public void testRemoveMatchesWithMultipleMatches() {
        // Given: Set up multiple match relationships
        roleA.matched.put(roleB.name, roleB);
        roleA.matched.put(roleC.name, roleC);
        roleB.matchedBy.put(roleA.name, roleA);
        roleC.matchedBy.put(roleA.name, roleA);

        // When: removeMatches is called on roleA
        roleA.removeMatches();

        // Then: roleA's matchedBy is cleared and related roles no longer reference roleA
        assertTrue(roleA.matchedBy.isEmpty());
        assertNull(roleB.matched.get(roleA.name));
        assertNull(roleC.matched.get(roleA.name));
    }

    @Test
    public void testRemoveMatchesDoesNotAffectOtherRelationships() {
        // Given: Set up complex relationships
        Role roleD = new Role("roleD");

        // roleA is matched by roleB and roleC
        roleA.matchedBy.put(roleB.name, roleB);
        roleA.matchedBy.put(roleC.name, roleC);

        // roleA is matched to roleD
        roleA.matched.put(roleD.name, roleD);
        roleD.matchedBy.put(roleA.name, roleA);

        // When: removeMatches is called on roleA
        roleA.removeMatches();

        // Then: roleA's matchedBy is cleared but its matched relationships remain
        assertTrue(roleA.matchedBy.isEmpty());
        assertFalse(roleA.matched.isEmpty());
        assertEquals(1, roleA.matched.size());
        assertNotNull(roleA.matched.get(roleD.name));
        assertNull(roleB.matched.get(roleA.name));
        assertNull(roleC.matched.get(roleA.name));
    }
}

